<?php
declare(strict_types=1);mysqli_report(MYSQLI_REPORT_ERROR|MYSQLI_REPORT_STRICT);$db=getenv('DB_NAME')?:'';if(!str_ends_with($db,'_test')&&!str_contains($db,'dev'))exit("Refusing to seed non-development/test database.\n");$c=new mysqli(getenv('DB_HOST')?:'127.0.0.1',getenv('DB_USER')?:'root',getenv('DB_PASS')?:'',$db,(int)(getenv('DB_PORT')?:3307));$c->set_charset('utf8mb4');$admin=(int)$c->query("SELECT id FROM users ORDER BY id LIMIT 1")->fetch_row()[0];$types=['land_dispute','ancestral_domain_conflict','cultural_rights_violation','discrimination','environmental_issue'];$c->begin_transaction();try{foreach($types as$i=>$type){$title='Fictional '.ucwords(str_replace('_',' ',$type));$exists=(int)$c->query("SELECT COUNT(*) FROM case_applications WHERE case_title='".$c->real_escape_string($title)."'")->fetch_row()[0];if($exists)continue;$typeId=(int)$c->query("SELECT id FROM case_types WHERE code='$type'")->fetch_row()[0];$assigned=$type==='land_dispute'?'assessor':'tribe_leader';$stmt=$c->prepare("INSERT INTO case_applications(applicant_fullname,applicant_ip_group,case_title,case_type,case_type_id,case_description,status,created_by,assigned_to) VALUES(?,'Test Tribe',?,?,?,'Fictional development case.','pending',?,?)");$applicant='Fictional Applicant '.($i+1);$stmt->bind_param('sssiss',$applicant,$title,$type,$typeId,$admin,$assigned);$stmt->execute();$cid=$c->insert_id;foreach([['complainant',$applicant],['respondent','Fictional Respondent '.($i+1)],['witness','Fictional Witness '.($i+1)]]as[$role,$name]){$stmt=$c->prepare('INSERT INTO case_persons_involved(case_id,person_name,role) VALUES(?,?,?)');$stmt->bind_param('iss',$cid,$name,$role);$stmt->execute();}if($i===0){$stmt=$c->prepare("INSERT INTO case_persons_involved(case_id,person_name,role,relationship_to_applicant) VALUES(?,'Fictional Representative','representative','Relative')");$stmt->bind_param('i',$cid);$stmt->execute();}}$c->commit();echo"Anonymized case fixtures seeded safely.\n";}catch(Throwable$e){$c->rollback();throw$e;}
